NS.GlobalStrings["TUTORIAL12"] = "You can drink to regain your mana faster. |cffffd200Right Click|r on a beverage to drink it.|n|nYou don't need to drink if your class does not use mana."
NS.GlobalStrings["TUTORIAL13"] = "You can learn a new talent in the talent interface.|n|nOpen the talents page by clicking the pulsing |cffffd200Talents Button|r on your action bar."
NS.GlobalStrings["TUTORIAL14"] = "You can go to your class trainer to learn new skills. |cffffd200Right Click|r on trainers to talk to them.|n|nTrainers are found in many towns or cities and always in your starting area. You may have to search around a little to find your trainer."
NS.GlobalStrings["TUTORIAL15"] = "You can move spells and abilities to your action bar by clicking the |cffffd200Spellbook & Abilities Button|r at the bottom center of the screen and then dragging the ability icon to your action bar.|n|nYou can also use a spell or ability from the Spellbook directly by clicking on it."
NS.GlobalStrings["TUTORIAL16"] = "You can look at your reputation with different groups in the world under the Reputation tab.|n|nClick on the |cffffd200Character Info Button|r to find the Reputation tab."
NS.GlobalStrings["TUTORIAL17"] = "You can reply to that player by hitting the R key and then typing a message, or by typing /w <theirname> and then the message."
NS.GlobalStrings["TUTORIAL18"] = "You can invite another player to your group by |cffffd200Right Clicking|r their portrait and selecting the |cffffd200Invite|r option from the popup menu.|n|nYou can leave a group by Right Clicking on your own portrait and choosing the option to leave the party."
NS.GlobalStrings["TUTORIAL19"] = "That is another real person playing a character. You can tell by the blue name above their head."
NS.GlobalStrings["TUTORIAL1_DWARF"] = "Quest givers have exclamation points (|TInterface\\OptionsFrame\\UI-OptionsFrame-NewFeatureIcon:0|t) over their heads. You can get a quest by talking to |cffffd200Joren Ironstock|r.|n|nTo talk to  |cffffd200Joren Ironstock|r you need to |cffffd200Right Click|r on him."
NS.GlobalStrings["TUTORIAL1_GNOME"] = "Quest givers have exclamation points (|TInterface\\OptionsFrame\\UI-OptionsFrame-NewFeatureIcon:0|t) over their heads. You can get a quest by talking to |cffffd200Nevin Twistwrench|r.|n|nTo talk to  |cffffd200Nevin Twistwrench|r you need to |cffffd200Right Click|r on him."
NS.GlobalStrings["TUTORIAL1_HUMAN"] = "Quest givers have exclamation points (|TInterface\\OptionsFrame\\UI-OptionsFrame-NewFeatureIcon:0|t) over their heads. You can get a quest by talking to |cffffd200Marshal McBride|r.|n|nTo talk to  |cffffd200Marshal McBride|r you need to |cffffd200Right Click|r on him."
NS.GlobalStrings["TUTORIAL1_NIGHTELF"] = "Quest givers have exclamation points (|TInterface\\OptionsFrame\\UI-OptionsFrame-NewFeatureIcon:0|t) over their heads. You can get a quest by talking to |cffffd200Ilthalaine|r.|n|nTo talk to  |cffffd200Ilthalaine|r you need to |cffffd200Right Click|r on him."
NS.GlobalStrings["TUTORIAL1_ORC"] = "Quest givers have exclamation points (|TInterface\\OptionsFrame\\UI-OptionsFrame-NewFeatureIcon:0|t) over their heads. You can get a quest by talking to |cffffd200Kaltunk|r.|n|nTo talk to  |cffffd200Kaltunk|r you need to |cffffd200Right Click|r on him."
