NS.GlobalStrings["TUTORIAL1_TAUREN"] = "Quest givers have exclamation points (|TInterface\\OptionsFrame\\UI-OptionsFrame-NewFeatureIcon:0|t) over their heads. You can get a quest by talking to |cffffd200Chief Hawkwind|r.|n|nTo talk to  |cffffd200Chief Hawkwind|r you need to |cffffd200Right Click|r on him."
